<?php
declare(strict_types=1);
namespace App\Http\Controllers;
use App\Application\Services\AdminCatalogService; use Swoole\Http\Request;
final class AdminCatalogController extends Controller { public function __construct(private AdminCatalogService $catalog){} public function products():array{return $this->ok($this->catalog->products());} public function createProduct(Request $r,array $d):array{return $this->created($this->catalog->createProduct($this->requireAuthUserId($r),$d));} public function updateProduct(Request $r,string $productId,array $d):array{return $this->ok($this->catalog->updateProduct($this->requireAuthUserId($r),$productId,$d));} public function publish(Request $r,string $productId):array{return $this->ok($this->catalog->productStatus($this->requireAuthUserId($r),$productId,'published'));} public function archive(Request $r,string $productId):array{return $this->ok($this->catalog->productStatus($this->requireAuthUserId($r),$productId,'archived'));} public function tiers(string $skuId):array{return $this->ok($this->catalog->tiers($skuId));} public function saveTiers(Request $r,string $skuId,array $d):array{return $this->ok($this->catalog->saveTiers($this->requireAuthUserId($r),$skuId,$d));} public function adjust(Request $r,array $d):array{return $this->created($this->catalog->adjustInventory($this->requireAuthUserId($r),$d));} }
